#!/usr/bin/env node
// Extract every theorem STATEMENT verbatim from the Lean 4 sources and write
// js/core/lean-source.js (generated; do not edit by hand). Proofs and definitions are
// deliberately not exported: the Lean development itself stays private.
//
//   node docs/tools/extract-lean.mjs [path/to/is_kmap_possible]
//
// Default source: /store/shuvam/E-motioner-X-SBS/lean_proofs/proofs/is_kmap_possible
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const DOCS = path.resolve(HERE, "..");
const SRC = process.argv[2] || "/store/shuvam/E-motioner-X-SBS/lean_proofs/proofs/is_kmap_possible";
const FILES = ["KmapProofs", "KmerIndexing", "AminoAcidEncoding", "ContactMapCompleteness",
  "KmapEncodingEquiv", "ContactCircuits", "SequenceCircuits"];

// A declaration ends at the next non-empty line that starts in column 0.
function blockEnd(lines, start) {
  let k = start + 1;
  while (k < lines.length && !(lines[k].length && !/^\s/.test(lines[k]))) k++;
  let end = k;
  while (end > start + 1 && lines[end - 1].trim() === "") end--;
  return end; // exclusive
}

function precedingDoc(lines, i) {
  // /-- ... -/ docstring directly above (only blank lines allowed between), else -- comments.
  let k = i - 1;
  while (k >= 0 && lines[k].trim() === "") k--;
  if (k >= 0 && lines[k].trim().endsWith("-/")) {
    let s = k;
    while (s >= 0 && !lines[s].includes("/-")) s--;
    if (s >= 0 && lines[s].trimStart().startsWith("/--")) return { doc: lines.slice(s, k + 1).join("\n"), comment: null };
    return { doc: null, comment: null };
  }
  const com = [];
  while (k >= 0 && lines[k].trimStart().startsWith("--")) { com.unshift(lines[k]); k--; }
  return { doc: null, comment: com.length ? com.join("\n") : null };
}

const theorems = [];
const defs = {};
const audit = Object.fromEntries(
  fs.readFileSync(path.join(SRC, "axiom_audit.tsv"), "utf8").trim().split("\n").slice(1)
    .map((l) => l.split("\t")).map(([m, t, ax]) => [`${m}.${t}`, (ax || "").split(",").filter(Boolean)]));

for (const mod of FILES) {
  const file = `${mod}.lean`;
  const text = fs.readFileSync(path.join(SRC, file), "utf8");
  const lines = text.split("\n");
  defs[mod] = {};
  for (let i = 0; i < lines.length; i++) {
    const L = lines[i];
    let m;
    if ((m = /^(def|inductive)\s+([A-Za-z_][\w']*)/.exec(L))) {
      const end = blockEnd(lines, i);
      defs[mod][m[2]] = lines.slice(i, end).join("\n");
      i = end - 1;
    } else if ((m = /^theorem\s+([A-Za-z_][\w']*)/.exec(L))) {
      const name = m[1];
      const end = blockEnd(lines, i);
      const block = lines.slice(i, end).join("\n");
      const at = block.search(/:=\s*by\b/);
      if (at < 0) throw new Error(`${mod}.${name}: no ':= by' proof marker`);
      const statement = block.slice(0, at).replace(/\s+$/, "");
      const proof = block.slice(at).replace(/^:=\s*/, "");
      const { doc, comment } = precedingDoc(lines, i);
      const id = `${mod}.${name}`;
      if (!(id in audit)) throw new Error(`${id} missing from axiom_audit.tsv`);
      const p = proof.replace(/\s+/g, " ").trim();
      const proofKind = p === "by native_decide" ? "native_decide" : p === "by decide" ? "decide" : "tactic";
      theorems.push({ id, module: mod, file, name, line: i + 1, statement, axioms: audit[id], proofKind });
      i = end - 1;
    }
  }
}

if (theorems.length !== 131) throw new Error(`expected 131 theorems, found ${theorems.length}`);
if (Object.keys(audit).length !== 131) throw new Error("audit row count != 131");
const nNative = theorems.filter((t) => t.axioms.some((a) => a.includes("native_decide"))).length;
const nNone = theorems.filter((t) => t.axioms.length === 0).length;

const out = `// GENERATED by docs/tools/extract-lean.mjs from the Lean 4 sources. Do not edit by hand.
// Theorem statements only, copied verbatim; the proofs and definitions stay in the (private)
// lean_proofs repository.
// ${theorems.length} theorems, ${nNative} depend on native_decide, ${nNone} depend on no axiom at all.
export const LEAN_FILES = ${JSON.stringify(FILES.map((m) => `${m}.lean`))};
export const THEOREM_SOURCES = ${JSON.stringify(theorems, null, 1)};
`;
fs.writeFileSync(path.join(DOCS, "js", "core", "lean-source.js"), out);
console.log(`extracted ${theorems.length} theorems (${nNative} native_decide, ${nNone} axiom-free), ` +
  `${Object.values(defs).reduce((a, d) => a + Object.keys(d).length, 0)} definitions`);
